        if 'clk' in v:
            prev_clk = v['clk']

        if rst:
            state = 1

        if rst:
            data_out = 0
            token_received = 1
            token = 0
        else:
            token_received = state & 0xF
            if state in (1, 2, 4, 8):
                token = ((state << 1) & 0xF) | (state >> 3)
                data_out = data_in if has else 0
            else:
                token = 0
                data_out = 0

        res.append({
